// MQTT 토픽에서 farmId 추출하여 보존 (응답에 포함)
const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

msg._farmId = farmId;
msg.payload = '';  // exec 노드 입력은 빈 문자열 (command 자체에 인자 없음)

node.status({ fill: 'blue', shape: 'dot', text: 'pm2 jlist ' + farmId });
return msg;

// pm2 jlist 의 stdout (JSON 배열) 파싱 후 process 별 status 추출
const farmId = msg._farmId || 'farm_0001';

let processes = [];
try {
    processes = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    if (!Array.isArray(processes)) processes = [];
} catch (e) {
    node.warn('pm2 jlist 파싱 실패: ' + e.message);
    return null;
}

function extract(name) {
    const p = processes.find(x => x.name === name);
    if (!p) return null;
    const env = p.pm2_env || {};
    return {
        status: env.status || 'unknown',
        uptime: env.pm_uptime || null,  // ms epoch (start time)
        restarts: env.restart_time || 0,
        unstableRestarts: env.unstable_restarts || 0,
        pid: p.pid || null,
        memory: p.monit?.memory || 0,
        cpu: p.monit?.cpu || 0,
    };
}

const status = {
    nodeRed: extract('node-red'),
    rpiExpress: extract('smartfarm-rpi'),
    smartfarmSystem: extract('smartfarm-system'),
};

msg.topic = 'smartfarm/' + farmId + '/system/status';
msg.payload = {
    ...status,
    farmId,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

const nrUp = status.nodeRed?.status === 'online' ? '✓' : '✗';
const expUp = status.rpiExpress?.status === 'online' ? '✓' : '✗';
node.status({
    fill: 'green', shape: 'dot',
    text: 'NR:' + nrUp + ' EXP:' + expUp + ' (' + new Date().toLocaleTimeString() + ')'
});
return msg;
